import unittest
from candidate import digitSum

class TestDigitSum(unittest.TestCase):
    def test_digitSum_empty_string_returns_zero(self):
        self.assertEqual(digitSum(""), 0)

    def test_digitSum_mixed_case_uppercase_sum(self):
        self.assertEqual(digitSum("abAB"), 131)

    def test_digitSum_lowercase_only_returns_zero(self):
        self.assertEqual(digitSum("abc"), 0)

    def test_digitSum_all_uppercase(self):
        self.assertEqual(digitSum("ABC"), 198)

    def test_digitSum_boundary_single_uppercase(self):
        self.assertEqual(digitSum("A"), 65)

    def test_digitSum_boundary_single_lowercase(self):
        self.assertEqual(digitSum("a"), 0)

    def test_digitSum_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(None)

    def test_digitSum_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(123)

    def test_digitSum_docstring_example_abcCd(self):
        self.assertEqual(digitSum("abcCd"), 67)

    def test_digitSum_docstring_example_helloE(self):
        self.assertEqual(digitSum("helloE"), 69)

    def test_digitSum_docstring_example_woArBld(self):
        self.assertEqual(digitSum("woArBld"), 131)

    def test_digitSum_docstring_example_aAaaaXa(self):
        self.assertEqual(digitSum("aAaaaXa"), 153)
